mapper.select:
select BOOKSET_ID
from BOK_BOOKSET
where BOOKSET_TYPE != #{booksetType}
and ACCT_SUBJECT_TYPE != #{acctSubjectType}

select BOOKSET_ID prodId, BOOKSET_NAME prodName from BOK_BOOKSET where 1 = 1
AND BOOKSET_ID IN
#{item}

select BOOKSET_ID prodId, BOOKSET_NAME prodName from BOK_BOOKSET where 1 = 1
AND BOOKSET_ID NOT IN
#{item}
AND (UPPER(BOOKSET_NAME) LIKE concat(concat('%', UPPER(#{prodName})),'%') OR UPPER(BOOKSET_ID) LIKE concat(concat('%', UPPER(#{prodName})),'%') )
and ACCT_SUBJECT_TYPE != #{acctSubjectTypeNo}
